def matches(event, branch, rule):
    if rule["event"] != event:
        return False
    allowed = rule.get("branches")
    if allowed is not None and branch not in allowed:
        return False
    return True

rules = [
    {"job": "test", "event": "pull_request", "branches": None},
    {"job": "deploy", "event": "push", "branches": ["main"]},
]

incoming = [
    ("pull_request", "feature/login"),
    ("push", "feature/login"),
    ("push", "main"),
]

for event, branch in incoming:
    triggered = [r["job"] for r in rules if matches(event, branch, r)]
    print(f"{event} en {branch}: {triggered or 'ningun job'}")
